# Write web/encounters.data.js from data/encounters.json (file:// friendly, UTF-8 no BOM).
$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $PSScriptRoot
$src = Join-Path $root "data\encounters.json"
$out = Join-Path $root "web\encounters.data.js"
if (-not (Test-Path $src)) { throw "Missing $src" }
$json = [System.IO.File]::ReadAllText($src)
$body = @"
/* auto-generated by scripts/embed-web-seed.ps1 — do not edit */
window.S2033 = window.S2033 || {};
window.S2033.SEED = $json;
"@
$utf8 = New-Object System.Text.UTF8Encoding $false
[System.IO.File]::WriteAllText($out, $body, $utf8)
Write-Host "Wrote $out"
